Definition iarm_0RB0LD_0LC1RD_1RB1LC_0RB1RA (d r : nat) : LRule :=
  match d, r with
  | 0, 0 => iarm0_0_0RB0LD_0LC1RD_1RB1LC_0RB1RA
  | 0, 1 => iarm0_1_0RB0LD_0LC1RD_1RB1LC_0RB1RA
  | _, _ => iarm0_0_0RB0LD_0LC1RD_1RB1LC_0RB1RA   (* unreachable: only d < b-1 and r < N0 + st *)
  end.

