  mkLRule (mkC StB (mkS [S1;S1;S1] [S1;S1;S1] 1 0 [S1]) S0 (mkS [] [] 0 0 []))
          (mkC StB (mkS [S0;S1;S1;S1;S1;S1] [S0;S1;S1] 1 0 [S1]) S0 (mkS [] [] 0 0 [])) 6 16.
